form .form-group.submit {
  justify-content: flex-end;
}

.dgtx-form {
  position: relative;
}

.dgtx-form .form-group .date-select .form-control {
  margin-right: 10px;
}

.dgtx-form .form-group.submit {
  border-top: 1px solid #eee;
